/// <summary>
/// runService
/// </summary>
/// <param name = "_dataContract">AVADAIExportProtocolCleanUpDataContract</param>
public void runService(AVADAIExportProtocolCleanUpDataContract _dataContract)
{
    QueryRun                    queryRun;
    AVADAIReportExportTable     reportExportTable;  

    // create a new queryrun object
    query query = _dataContract.getQuery();
    query.dataSourceTable(tableNum(AVADAIReportExportTable)).update(true);
    queryRun    = new queryRun(query);

    // loop all results from the query
    ttsbegin;
    while(queryRun.next())
    {
        reportExportTable = queryRun.get(tableNum(AVADAIReportExportTable));
        reportExportTable.delete();
    }
    ttscommit;
}
